document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{const on=b.dataset.photo==='on';const image=document.querySelector('#jdl-main');image.src='/assets/jdl-2021-156p/'+b.dataset.photo+'.png';image.alt='JDL 2021-156P 24V flexible LED strip light '+(on?'illuminated':'unlit')+' on white background';document.querySelectorAll('[data-photo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));